  seats: string[];
  form: FormValues;
  paid: boolean;
  email: string | null;
}
EOF
cat > dates.ts <<'EOF'
const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

const pad = (n: number) => String(n).padStart(2, '0');

export function toIso(d: Date): string {
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}

export function parseIso(s: string | null | undefined): Date | null {
  const m = s ? /^(\d{4})-(\d{2})-(\d{2})$/.exec(s) : null;
  if (!m) return null;
  const [y, mo, da] = [Number(m[1]), Number(m[2]), Number(m[3])];
  const d = new Date(y, mo - 1, da);
  return d.getFullYear() === y && d.getMonth() === mo - 1 && d.getDate() === da ? d : null;
}

export function weekday(d: Date): string {
  return WEEKDAYS[d.getDay()];
}

export function showDate(isoDate: string, time: string): string {
  const d = parseIso(isoDate);
  if (!d) return `${isoDate} ${time}`;
  return `${weekday(d)} ${d.getDate()} ${MONTHS[d.getMonth()]} ${time}`;
}

export function formatPrice(n: number): string {
  return `${n.toFixed(2)} PLN`;
}
EOF
cat > seat-utils.ts <<'EOF'
export interface TicketItem {
  kind: 'seat' | 'couch';
  row: number;
  colStart: number;
  colEnd: number;
  ids: string[];
  price: number;
}

export const MAX_SEATS = 10;
export const COUCH_ROW = 15;

export const seatId = (row: number, col: number) => `R${row}C${col}`;

export function parseSeatId(id: string): { row: number; col: number } | null {
  const m = /^R(\d+)C(\d+)$/.exec(id);
  return m ? { row: Number(m[1]), col: Number(m[2]) } : null;
}

export function seatPrice(row: number): number {
  if (row <= 5) return 25;
  if (row <= 10) return 32;
  return 39;
}

export function buildItems(ids: string[]): TicketItem[] {
  const seen = new Set<string>();
  const items: TicketItem[] = [];
  for (const id of ids) {
    const p = parseSeatId(id);
    if (!p) continue;
    if (p.row === COUCH_ROW) {
      const start = p.col % 2 === 1 ? p.col : p.col - 1;
      const key = seatId(p.row, start);
      if (seen.has(key)) continue;
      seen.add(key);
      items.push({
        kind: 'couch',
        row: p.row,
        colStart: start,
        colEnd: start + 1,
        ids: [key, seatId(p.row, start + 1)],
        price: 89,
      });
    } else {
      if (seen.has(id)) continue;
      seen.add(id);
      items.push({ kind: 'seat', row: p.row, colStart: p.col, colEnd: p.col, ids: [id], price: seatPrice(p.row) });
    }
  }
