      <div class="field">
        <mat-form-field appearance="outline" subscriptSizing="dynamic">
          <mat-label [attr.data-testid]="f.testId + '-label'">{{ f.label }}</mat-label>
          <input matInput type="text" [formControlName]="f.name" [attr.data-testid]="f.testId + '-input'" />
        </mat-form-field>
        @if (message(f.name); as msg) {
          <div class="error" [attr.data-testid]="f.testId + '-error'">{{ msg }}</div>
        }
      </div>
    }

    <div class="field">
      <mat-checkbox formControlName="terms" data-testid="terms-checkbox" (change)="touchTerms()">
        <span data-testid="terms-label">I accept the terms and conditions *</span>
      </mat-checkbox>
      @if (message('terms'); as msg) {
        <div class="error" data-testid="terms-error">{{ msg }}</div>
      }
    </div>

    <div class="actions">
      <button mat-stroked-button type="button" data-testid="checkout-back-button" (click)="back()">Back</button>
      <button mat-flat-button type="submit" data-testid="pay-button" [disabled]="paying()">
        {{ paying() ? 'Processing…' : 'Pay ' + formatPrice(booking.total()) }}
      </button>
    </div>
  </form>
</div>
